import { chromium } from 'playwright';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
await page.goto('http://localhost:6006/iframe.html?id=commerce-zimmcartdrawer--default&viewMode=story', { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(1500);

const result = await page.evaluate(() => {
  const cs = (el) => {
    if (!el) return null;
    const s = getComputedStyle(el);
    return { fontSize: s.fontSize, fontWeight: s.fontWeight, lineHeight: s.lineHeight, color: s.color, paddingTop: s.paddingTop, paddingLeft: s.paddingLeft };
  };
  const heading = Array.from(document.querySelectorAll('*')).find(el => /BAG/.test(el.textContent || '') && el.children.length === 0);
  const closeBtn = document.querySelector('button[aria-label*="lose" i], button[aria-label*="Close" i]');
  const header = heading?.closest('div');
  const headerRect = header?.getBoundingClientRect();
  const closeBtnRect = closeBtn?.getBoundingClientRect();
  const closeSvg = closeBtn?.querySelector('svg');
  const closeSvgRect = closeSvg?.getBoundingClientRect();
  return {
    headingText: heading?.textContent,
    headingStyle: cs(heading),
    headerRect: headerRect ? { w: headerRect.width, h: headerRect.height, top: headerRect.top, left: headerRect.left } : null,
    closeBtnRect: closeBtnRect ? { w: closeBtnRect.width, h: closeBtnRect.height } : null,
    closeSvgRect: closeSvgRect ? { w: closeSvgRect.width, h: closeSvgRect.height } : null,
    closeBtnAriaLabel: closeBtn?.getAttribute('aria-label'),
  };
});
console.log('DEFAULT STORY:', JSON.stringify(result, null, 2));
await browser.close();

